changeSet.sql:
ALTER TABLE public.tenant_tournament ADD COLUMN short_label character varying(40);

UPDATE public.tenant_tournament
SET short_label = LEFT(btrim(title), 40)
WHERE short_label IS NULL OR btrim(short_label) = '';

UPDATE public.tenant_tournament
SET short_label = 'Capital Cup'
WHERE slug = 'capital-cup-2026';

UPDATE public.tenant_tournament
SET short_label = 'Capital Cup 2025'
WHERE slug = 'capital-cup-2025';

ALTER TABLE public.tenant_tournament ALTER COLUMN short_label SET NOT NULL;
ALTER TABLE public.tenant_tournament ALTER COLUMN edition_year DROP NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS ux_tenant_tournament__tenant_short_label
    ON public.tenant_tournament (tenant_id, short_label);

COMMENT ON COLUMN public.tenant_tournament.short_label IS 'Unique menu label shown in the public header when this tournament is selected.';
COMMENT ON COLUMN public.tenant_tournament.edition_year IS 'Optional year. Not used in the header label.';
COMMENT ON TABLE public.tenant_tournament IS 'Tenant-hosted tournaments. The header shows the short label of the tournament marked show_in_header.';
